diff --git a/waitgroup.go b/waitgroup.go
index 2306877..d2a8f91 100644
--- a/waitgroup.go
+++ b/waitgroup.go
@@ -18,7 +18,7 @@ type WaitGroup struct {
 func (h *WaitGroup) Go(f func()) {
 	h.wg.Add(1)
 	go func() {
-		defer h.done()
+		defer h.wg.Done()
 		h.pc.Try(f)
 	}()
 }
@@ -31,9 +31,3 @@ func (h *WaitGroup) Wait() {
 	// Propagate a panic if we caught one from a child goroutine
 	h.pc.Repanic()
 }
-
-// done should be called in a defer statement in a child goroutine.
-// It catches any panics and decrements the counter.
-func (h *WaitGroup) done() {
-	h.wg.Done()
-}
